class Rand
{
private:
    int count = 0;
    vec_int rand_arr;

public:
    Rand(){
        rep(i, RAND_ARR_LEN){
            rand_arr.push_back(dist(mt));
}
}
;
int get();
int get_rand(int from, int to);
float get_float();
}
;

int Rand::get()
{
    int num = rand_arr.at(count);
    count += 1;
    count %= RAND_ARR_LEN;
    return num;
}

int Rand::get_rand(int from, int to)
{
    int diff = to - from;
    int num = get() % diff;
    return num + from;
}

float Rand::get_float()
{
    // 0~1の間の一様乱数
    return (float)get() / (float)RAND_RANGE;
}

Rand ro;

float get_time(bool init)
{
    static std::chrono::system_clock::time_point start;
    if (init)
    {
        start = std::chrono::system_clock::now();
    }
    std::chrono::system_clock::time_point end = std::chrono::system_clock::now();
    return std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count(); //処理に要した時間をミリ秒に変換
}

vec_int make_edge_count_ranking(string graph)
{
    vec_int edge_count_ranking = vec_int(N, 0);
    int ind = 0;
    for (int i = 0; i < N; i++)
    {
        for (int j = i + 1; j < N; j++)
        {
            if (graph.at(ind) == '1')
            {
                edge_count_ranking.at(i)++;
                edge_count_ranking.at(j)++;
            }
            ind++;
        }
    }
    sort(edge_count_ranking.begin(), edge_count_ranking.end());
    reverse(edge_count_ranking.begin(), edge_count_ranking.end());
    return edge_count_ranking;
}

class EncodedBits
{
public:
    int id;
    int bit_len;
    int one_count;
    vector<vec_int> mat;
    vector<int> edge_count_ranking;
    string bits;
    EncodedBits(){};
    EncodedBits(int _id, int _bit_len, vector<vec_int> &matrix);
    void cout_bits() { cout << bits << endl
                            << flush; };
    float distance_between_rankings(vec_int &ranking);
    double distance_between_rankings2(vec_int &ranking);
    vec_int make_simulated_ranking();

    vector<vec_int> ranking_distributions;
    vector<double> ranking_mean;
    vector<double> ranking_sigma;
    vector<vec_int> ranking_distribution_counts;
    void make_ranking_count_distribution();
};

EncodedBits::EncodedBits(int _id, int _bit_len, vector<vec_int> &matrix)
{
    id = _id;
    bit_len = _bit_len;
    mat = matrix;
    bits = "";
    for (int i = 0; i < N; i++)
    {
        for (int j = i + 1; j < N; j++)
        {
            if (mat.at(i).at(j) == 1)
            {
                bits += '1';
            }
            else
            {
                bits += '0';
            }
        }
    }
    edge_count_ranking = make_edge_count_ranking(bits);
}

float EncodedBits::distance_between_rankings(vec_int &ranking)
{
    float result = 0.;
    float tot1 = 0.;
    float tot2 = 0.;
    for (int i = 0; i < N; i++)
    {
        int count = edge_count_ranking.at(i);
        float expected = (float)count * (1. - epsilon) + ((float)N - count) * epsilon;
        tot1 += ranking.at(i);
        tot2 += expected;
        result += pow(fabs((float)ranking.at(i) - expected), 4.0);
    }
    result += pow(fabs(tot1 - tot2), 2.0);
    return result;
}

double EncodedBits::distance_between_rankings2(vec_int &ranking)
{
    sort(ranking.begin(), ranking.end());
    reverse(ranking.begin(), ranking.end());
    double result = 0.;
    double tot1 = 0.;
    double tot2 = 0.;
    for (int i = 0; i < N; i++)
    {
        double count = (double)ranking.at(i);
        result += max(0., pow(fabs(ranking_mean.at(i) - count), pow_ind) - pow(10, -20));
    }
    return result;
}

void EncodedBits::make_ranking_count_distribution()
{
    ranking_distributions = vector<vec_int>(N);
    ranking_distribution_counts = vector<vec_int>(N, vec_int(N, 0));
    ranking_mean = vector<double>(N, 0);
    ranking_sigma = vector<double>(N, 0);
    int repeat = 400;
    for (int i = 0; i < repeat; i++)
    {
        vec_int ranking = make_simulated_ranking();
        for (int j = 0; j < N; j++)
        {
            ranking_distributions.at(j).push_back(ranking.at(j));
            ranking_distribution_counts.at(j).at(ranking.at(j))++;
            ranking_mean.at(j) += ((double)ranking.at(j)) / ((double)repeat);
        }
    }

    for (int i = 0; i < repeat; i++)
    {
        for (int j = 0; j < N; j++)
        {
            ranking_sigma.at(j) += pow(((double)ranking_distributions.at(j).at(i) - ranking_mean.at(j)), 2) / (double)repeat;
        }
    }
    for (int j = 0; j < N; j++)
    {
        ranking_sigma.at(j) = sqrt(ranking_sigma.at(j));
    }
}

vec_int EncodedBits::make_simulated_ranking()
{
    vec_int result_vec(N, 0);
    for (int i = 0; i < N; i++)
    {
        for (int j = i + 1; j < N; j++)
        {
            bool flip = ro.get_float() < epsilon;
            if (flip)
            {
                result_vec.at(i) += 1 - mat.at(i).at(j);
                result_vec.at(j) += 1 - mat.at(j).at(i);
            }
            else
            {
                result_vec.at(i) += mat.at(i).at(j);
                result_vec.at(j) += mat.at(j).at(i);
            }
        }
    }
    sort(result_vec.begin(), result_vec.end());
    reverse(result_vec.begin(), result_vec.end());
    return result_vec;
}

int speculate_original_signal(string &noisy_signal, vector<EncodedBits> &encoded_vec)
{
    vec_int ranking = make_edge_count_ranking(noisy_signal);
    int result = -1;
    double distance = (float)INT_MAX;
    for (int i = 0; i < M; i++)
    {
        double tmp = encoded_vec.at(i).distance_between_rankings2(ranking);
        // double tmp = encoded_vec.at(i).distance_between_rankings(ranking);
        if (tmp < distance)
        {
            distance = tmp;
            result = i;
        }
    }
    return result;
}

