int determine_N()
{
    int e = (int)(epsilon * 100 + 0.01);
    // cerr << "e=" << e << endl;
    return N_arr.at(M - 10).at(e);
}

float distance_between_(vec_int &ranking1, vec_int &ranking2)
{
    float result = 0.;
    for (int i = 0; i < N; i++)
    {
        int count1 = ranking1.at(i);
        float expected1 = (float)count1 * (1. - epsilon) + ((float)N - count1) * epsilon;
        int count2 = ranking2.at(i);
        float expected2 = (float)count2 * (1. - epsilon) + ((float)N - count2) * epsilon;
        result += ((expected1 - expected2) * (expected1 - expected2));
    }
    return result;
}

void make_star_graph(vector<vec_int> &mat, int edge_count)
{
    int count = 0;
    for (int i = 0; i < N; i++)
    {
        for (int j = i + 1; j < N; j++)
        {
            if (count >= edge_count)
                return;
            mat.at(i).at(j) = 1;
            mat.at(j).at(i) = 1;
            count++;
            if (count >= edge_count)
                return;
        }
    }
}

void make_dense_graph(vector<vec_int> &mat, int edge_count)
{
    int count = 0;
    for (int i = 1; i < N; i++)
    {
        if (count >= edge_count)
            break;
        for (int j = 0; j < i; j++)
        {
            mat.at(i).at(j) = 1;
            mat.at(j).at(i) = 1;
            count++;
            if (count >= edge_count)
                return;
        }
    }
}

void make_star_dense_graph(vector<vec_int> &mat, float ratio, int edge_count)
{
    // スターグラフ優先+密結合
    int count = 0;
    for (int i = 0; i < N; i++)
    {
        for (int j = i + 1; j < N; j++)
        {
            if (count >= (float)edge_count * ratio)
                goto OUT1;
            mat.at(i).at(j) = 1;
            mat.at(j).at(i) = 1;
            count++;
            if (count >= (float)edge_count * ratio)
                goto OUT1;
        }
    }
OUT1:
    for (int i = 1; i < N; i++)
    {
        if (count >= edge_count)
            return;
        for (int j = 0; j < i; j++)
        {
            if (mat.at(i).at(j) == 1)
                continue;
            mat.at(i).at(j) = 1;
            mat.at(j).at(i) = 1;
            count++;
            if (count >= edge_count)
                return;
        }
    }
}

void make_star_sparse_graph(vector<vec_int> &mat, float ratio, int edge_count)
{
    // スターグラフ優先+疎結合
    int count = 0;
    for (int i = 0; i < N; i++)
    {
        for (int j = i + 1; j < N; j++)
        {
            if (count >= (float)edge_count * ratio)
                goto OUT2;
            mat.at(i).at(j) = 1;
            mat.at(j).at(i) = 1;
            count++;
            if (count >= (float)edge_count * ratio)
                goto OUT2;
        }
    }
OUT2:
    for (int i = 1; i < N; i++)
    {
        if (count >= edge_count)
            return;
        for (int j = 0; j < N - i; j++)
        {
            if (mat.at(j).at(j + i) == 1)
                continue;
            mat.at(j).at(j + i) = 1;
            mat.at(j + i).at(j) = 1;
            count++;
            if (count >= edge_count)
                return;
        }
    }
}

void make_dense_sparse_map(vector<vec_int> &mat, float ratio, int edge_count)
{
    // 密結合+疎結合
    int count = 0;
    for (int i = 1; i < N; i++)
    {
        for (int j = 0; j < i; j++)
        {
            if (count >= (float)edge_count * ratio)
                goto OUT3;
            mat.at(i).at(j) = 1;
            mat.at(j).at(i) = 1;
            count++;
            if (count >= (float)edge_count * ratio)
                goto OUT3;
        }
    }
OUT3:
    for (int i = 1; i < N; i++)
    {
        if (count >= edge_count)
            return;
        for (int j = 0; j < N - i; j++)
        {
            if (mat.at(j).at(j + i) == 1)
                continue;
            mat.at(j).at(j + i) = 1;
            mat.at(j + i).at(j) = 1;
            count++;
            if (count >= edge_count)
                return;
        }
    }
}

void make_both_side_map(vector<vec_int> &mat, float ratio, int edge_count)
{
    // 両サイドから密結合
    int count = 0;
    for (int i = 1; i < N; i++)
    {
        for (int j = 0; j < i; j++)
        {
            if (count >= (float)edge_count * ratio)
                goto OUT4;
            mat.at(i).at(j) = 1;
            mat.at(j).at(i) = 1;
            count++;
            if (count >= (float)edge_count * ratio)
                goto OUT4;
        }
    }
OUT4:
    for (int i = 1; i < N; i++)
    {
        for (int j = 0; j < i; j++)
        {
            if (count >= edge_count)
                return;
            if (mat.at(N - i - 1).at(N - j - 1) == 1)
                continue;
            mat.at(N - i - 1).at(N - j - 1) = 1;
            mat.at(N - j - 1).at(N - i - 1) = 1;
            count++;
            if (count >= edge_count)
                return;
        }
    }
}

void make_right_up_map(vector<vec_int> &mat, int edge_count)
{
    int count = 0;
    for (int i = 0; i < N; i++)
    {
        for (int h = 0; h <= i && h < N - i; h++)
        {
            if (mat.at(h).at(i) == 1)
                continue;
            mat.at(h).at(N - 1 - i) = 1;
            mat.at(N - 1 - i).at(h) = 1;
            count++;

            if (count >= edge_count)
                return;
        }
        for (int w = N - 1; w > i && w > N - 1 - i; w--)
        {
            if (mat.at(i).at(w) == 1)
                continue;
            mat.at(w).at(i) = 1;
            mat.at(i).at(w) = 1;
            count++;

            if (count >= edge_count)
                return;
        }
    }
}

void make_itimatsu_star_map(vector<vec_int> &mat, int edge_count)
{
    int count = 0;
    for (int i = 0; i < N; i++)
    {
        for (int j = i + 1; j < N; j++)
        {
            if ((i + j) % 2 == 0)
                continue;
            mat.at(i).at(j) = 1;
            mat.at(j).at(i) = 1;
            count++;
            if (count >= edge_count)
                return;
        }
    }

    for (int i = 0; i < N; i++)
    {
        for (int j = i + 1; j < N; j++)
        {
            if ((i + j) % 2 == 1)
                continue;
            mat.at(i).at(j) = 1;
            mat.at(j).at(i) = 1;
            count++;
            if (count >= edge_count)
                return;
        }
    }
}

void make_itimatsu_dense_map(vector<vec_int> &mat, int edge_count)
{
    int count = 0;
    for (int i = 1; i < N; i++)
    {
        for (int j = 0; j < i; j++)
        {
            if ((i + j) % 2 == 0)
                continue;
            mat.at(i).at(j) = 1;
            mat.at(j).at(i) = 1;
            count++;
            if (count >= edge_count)
                return;
        }
    }

    for (int i = 1; i < N; i++)
    {
        for (int j = 0; j < i; j++)
        {
            if ((i + j) % 2 == 1)
                continue;
            mat.at(i).at(j) = 1;
            mat.at(j).at(i) = 1;
            count++;
            if (count >= edge_count)
                return;
        }
    }
}

vector<vec_int> make_matrix(int type, int id)
{
    vector<vec_int> result(N, vec_int(N, 0));
    int edge_count = (((N * (N - 1)) / 2) / (M - 1)) * (id);

    switch (type)
    {
    case 0:
        make_star_graph(result, edge_count);
        break;
    case 1:
        make_dense_graph(result, edge_count);
        break;
    case 2:
        make_star_dense_graph(result, 0.25, edge_count);
        break;
    case 3:
        make_star_dense_graph(result, 0.5, edge_count);
        break;
    case 4:
        make_star_dense_graph(result, 0.75, edge_count);
        break;
    case 5:
        make_star_sparse_graph(result, 0.75, edge_count);
        break;
    case 6:
        make_star_sparse_graph(result, 0.25, edge_count);
        break;
    case 7:
        make_star_sparse_graph(result, 0.5, edge_count);
        break;
    case 8:
        make_dense_sparse_map(result, 0.25, edge_count);
        break;
    case 9:
        make_dense_sparse_map(result, 0.5, edge_count);
        break;
    case 10:
        make_dense_sparse_map(result, 0.75, edge_count);
        break;
    case 11:
        make_both_side_map(result, 0.25, edge_count);
        break;
    case 12:
        make_both_side_map(result, 0.50, edge_count);
        break;
    case 13:
        make_both_side_map(result, 0.75, edge_count);
        break;
    case 14:
        make_right_up_map(result, edge_count);
        break;
    case 15:
        make_itimatsu_dense_map(result, edge_count);
        break;
    case 16:
        make_itimatsu_star_map(result, edge_count);
        break;
    }

    return result;
}

vec_int selection_vec;

int get_int_and_go_next(int &ind, string &str)
{
    char ch = str.at(ind);
    ind++;
    if ((int)ch >= 40 && (int)ch <= 90)
    {
        return (int)ch - 40;
    }
    else if ((int)ch >= 97 && (int)ch <= 122)
    {
        return (int)ch - 97 + 51;
    }
    else if ((int)ch == 126)
    {
        ch = str.at(ind);
        ind++;
        int len = (int)ch - (int)'0';

        string num = "";
        int count = 0;
        while (count < len)
        {
            num += str.at(ind);
            ind++;
            count++;
        }
        return stoi(num);
    }
}
