int N_ind_val()
{
    int count = 0;
    for (int i = 5; i <= 100; i++)
    {
        if (i >= 50 && i % 4 != 0)
            continue;

        if (i < 50 && i >= 15 && i % 2 != 0)
            continue;
        if (i == N)
        {
            return count;
        }
        count++;
    }
    return count - 1;
}

vec_int decode(int ind)
{
    int base_num = 0;
    int ind2 = M - 10;
    string str;
    if (epsilon < 0.3)
    {
        str = selection_string_vec_small.at(ind).at(ind2);
    }
    else
    {
        str = selection_string_vec_large.at(ind).at(ind2);
    }

    vec_int result;
    int index = 0;
    while (index < str.size())
    {
        int num = get_int_and_go_next(index, str);
        base_num += num;
        result.push_back(base_num);
    }
    return result;
}

void make_encoded_vec(vector<EncodedBits> &encoded_vec)
{
    int ind = (N - 10) / 5;
    for (int i = 0; i < M; i++)
    {
        int id = selection_vec.at(i);
        vector<vec_int> mat = make_matrix(id / M, id % M);
        encoded_vec.at(i) = EncodedBits(i, (N * (N - 1) / 2), mat);
        encoded_vec.at(i).cout_bits();
        encoded_vec.at(i).make_ranking_count_distribution();
    }
}

void dfs(vector<vec_int> &result, vec_int &vec, int val, int res)
{
    if (res == 0)
    {
        result.push_back(vec);
        return;
    }
    for (int next_val = val - 1; next_val >= 1; next_val--)
    {
        if (next_val > res)
            continue;

        vec.push_back(next_val);
        dfs(result, vec, next_val, res - next_val);
        vec.pop_back();
    }
}

vector<vec_int> list_up_combinations(int val)
{
    vector<vec_int> result;
    vec_int tmp;
    dfs(result, tmp, val + 1, val);
    return result;
}

class Connected
{
public:
    int node_count;
    int edge_count;
    Connected(int node, int edge)
    {
        node_count = node;
        edge_count = edge;
    }
    void cout_info()
    {
        cout << node_count << " " << edge_count << endl;
    }
};

void dfs2(vector<vector<Connected>> &result, vector<Connected> &vec, vec_int combi, int ind)
{
    if (ind == combi.size())
    {
        result.push_back(vec);
        return;
    }
    int count = combi.at(ind);
    int max_edge = (count * (count - 1)) / 2;
    int min_edge = count - 1;
    for (int i = min_edge; i <= max_edge; i++)
    {
        vec.push_back(Connected(count, i));
        dfs2(result, vec, combi, ind + 1);
        vec.pop_back();
    }
}

vector<vector<Connected>> make_graphs(vector<vec_int> combis)
{
    vector<vector<Connected>> result;

    for (vec_int combi : combis)
    {
        vector<Connected> vec;
        dfs2(result, vec, combi, 0);
    }
    return result;
}

class Graph
{
public:
    string bits;
    int cc_count;
    vec_int cc_size_vec;
    vec_int cc_edge_size_vec;
    vector<vec_int> graph;
    bool is_same(vector<P> decoded);

    Graph(vector<Connected> conn);
};

bool Graph::is_same(vector<P> decoded)
{
    if (cc_count != decoded.size())
        return false;
    for (int i = 0; i < cc_count; i++)
    {
        if (!(decoded.at(i).first == cc_size_vec.at(i) && decoded.at(i).second == cc_edge_size_vec.at(i)))
        {
            return false;
        }
    }
    return true;
}

Graph::Graph(vector<Connected> conn)
{
    cc_count = conn.size();
    for (int i = 0; i < cc_count; i++)
    {
        cc_size_vec.push_back(conn.at(i).node_count);
        cc_edge_size_vec.push_back(conn.at(i).edge_count);
    }
    bits = "";
    graph = vector<vec_int>(N, vec_int(N, 0));

    int offset = 0;
    for (int i = 0; i < cc_count; i++)
    {
        int node_count = cc_size_vec.at(i);
        int edge_count = cc_edge_size_vec.at(i);

        int count = 0;
        for (int i = 1; i < node_count; i++)
        {
            if (count >= edge_count)
                break;
            for (int j = 0; j < node_count - i; j++)
            {
                graph.at(offset + j).at(offset + j + i) = 1;
                graph.at(offset + j + i).at(offset + j) = 1;
                count++;
                if (count >= edge_count)
                    break;
            }
        }
        offset += node_count;
    }
    bits = "";
    for (int i = 0; i < N; i++)
    {
        for (int j = i + 1; j < N; j++)
        {
            if (graph.at(i).at(j) == 1)
            {
                bits += '1';
            }
            else
            {
                bits += '0';
            }
        }
    }
}

vector<P> decode(string signal)
{
    vector<vec_int> graph(N, vec_int(N, 0));
    dsu uf_tree(N);
    int count = 0;
    vector<int> edge_count_vec(N, 0);
    for (int i = 0; i < N; i++)
    {
        for (int j = i + 1; j < N; j++)
        {
            if (signal.at(count) == '1')
            {
                uf_tree.merge(i, j);
                edge_count_vec.at(i) += 1;
                edge_count_vec.at(j) += 1;
            }
            count++;
        }
    }
    vector<vec_int> groups = uf_tree.groups();
    vector<P> result;
    for (vec_int group : groups)
    {
        int node_count = group.size();
        int edge_count = 0;
        for (int node : group)
        {
            edge_count += edge_count_vec.at(node);
        }
        edge_count /= 2;
        result.push_back(make_pair(node_count, edge_count));
    }
    sort(result.begin(), result.end());
    reverse(result.begin(), result.end());

    return result;
}

void solve(int M)
{
    vector<int> nums = {13, 24, 46, 78, 150}; //全部5から
    for (int i = 0; i < 5; i++)
    {
        if (M <= nums.at(i))
        {
            N = 5 + i;
            break;
        }
    }
    cout << N << endl
         << flush;
    vector<vec_int> combis = list_up_combinations(N);
    vector<vector<Connected>> connections = make_graphs(combis);
    vector<Graph> graphs;
    set<string> bit_set;
    for (int i = 0; i < M; i++)
    {
        graphs.push_back(Graph(connections.at(i)));
        cout << graphs.at(i).bits << endl
             << flush;
    }
    for (int k = 0; k < 100; k++)
    {
        string input_str;
        cin >> input_str;
        vector<P> decoded = decode(input_str);
        int result = -1;
        for (int i = 0; i < M; i++)
        {
            if (graphs.at(i).is_same(decoded))
            {
                result = i;
                break;
            }
        }
        if (result == -1)
        {
            result = 0;
        }
        cout << result << endl
             << flush;
    }
}

int main()
{
    get_time(true);
    cin >> M >> epsilon;
    if (epsilon < 0.009)
    {
        solve(M);
        return 0;
    }
    N = determine_N();

    int best_N = -1;
    int diff = 1000;

    for (int i = 5; i <= 100; i++)
    {
        if (i >= 50 && i % 4 != 0)
            continue;

        if (i < 50 && i >= 15 && i % 2 != 0)
            continue;

        int d = abs(i - N);
        if (diff > d)
        {
            diff = d;
            best_N = i;
        }
    }
    N = best_N;

    cout
        << N << endl
        << flush;

    vector<EncodedBits> encoded_vec(M);
    selection_vec = decode(N_ind_val());
    make_encoded_vec(encoded_vec);

    for (int k = 0; k < 100; k++)
    {
        string input_str;
        cin >> input_str;
        int result = speculate_original_signal(input_str, encoded_vec);

        cout
            << result << endl
            << flush;
    }

    return 0;
}